    54  BCProviderFromSrc::BCProviderFromSrc(
    55      std::unique_ptr<hbc::BytecodeModule> module)
    56      : module_(std::move(module)) {
    57    options_ = module_->getBytecodeOptions();
    58
    59    functionCount_ = module_->getNumFunctions();
    60
    61    globalFunctionIndex_ = module_->getGlobalFunctionIndex();
    62
    63    stringKinds_ = module_->getStringKinds();
    64    identifierHashes_ = module_->getIdentifierHashes();
    65    stringCount_ = module_->getStringTable().size();
    66    stringStorage_ = module_->getStringStorage();
    67
    68    regExpStorage_ = module_->getRegExpStorage();
    69    regExpTable_ = module_->getRegExpTable();
    70
    71    arrayBuffer_ = module_->getArrayBuffer();
    72    objKeyBuffer_ = module_->getObjectBuffer().first;
    73    objValueBuffer_ = module_->getObjectBuffer().second;
    74
    75    cjsModuleOffset_ = module_->getCJSModuleOffset();
    76    cjsModuleTable_ = module_->getCJSModuleTable();
    77    cjsModuleTableStatic_ = module_->getCJSModuleTableStatic();
    78
    79    debugInfo_ = &module_->getDebugInfo();
    80
    81    // Since we are executing from source, the serialization step that normally
    82    // takes care of putting the jump table into the bytecode is not run and hence
    83    // we do it here instead.
    84    module_->inlineJumpTables();
    85  }
